const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Sofia Martinez's orders
console.log('=== SOFIA MARTINEZ ORDERS ===');
const orders = db.prepare('SELECT * FROM orders WHERE customer_id = ?').all('cust_003');
orders.forEach(o => console.log(JSON.stringify(o)));

// Sofia's order items
console.log('\n=== SOFIA ORDER ITEMS ===');
const orderIds = orders.map(o => o.order_id);
if (orderIds.length > 0) {
  const items = db.prepare('SELECT * FROM order_items WHERE order_id IN (' + orderIds.map(() => '?').join(',') + ')').all(...orderIds);
  items.forEach(i => console.log(JSON.stringify(i)));
}

// Sofia's warranties
console.log('\n=== SOFIA WARRANTIES ===');
if (orderIds.length > 0) {
  const warranties = db.prepare('SELECT * FROM warranties WHERE order_id IN (' + orderIds.map(() => '?').join(',') + ')').all(...orderIds);
  warranties.forEach(w => console.log(JSON.stringify(w)));
}
"
